--
-- Table structure for table `personnel_avances`
--

DROP TABLE IF EXISTS `personnel_avances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `personnel_avances` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_personnel` int NOT NULL,
  `mois` int NOT NULL,
  `annee` int NOT NULL,
  `observation` varchar(255) NOT NULL,
  `montant` decimal(15,2) NOT NULL,
  `type` enum('credit','gratification') NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_personnel` (`id_personnel`),
  CONSTRAINT `personnel_avances_ibfk_1` FOREIGN KEY (`id_personnel`) REFERENCES `personnels` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb3;
